const incrocioLat = 44.3995;
const incrocioLon = 8.9851;

// 1. TRAFFIC FILTER
let ambLat = msg.payload.latitude;
let ambLon = msg.payload.longitude;
let sirena = msg.payload.siren_active;

if (ambLat === undefined || ambLon === undefined) {
    return null;
}

function calcolaDistanza(lat1, lon1, lat2, lon2) {
    const R = 6371e3;
    const p1 = lat1 * Math.PI / 180;
    const p2 = lat2 * Math.PI / 180;
    const deltaP = (lat2 - lat1) * Math.PI / 180;
    const deltaLambda = (lon2 - lon1) * Math.PI / 180;
    const a = Math.sin(deltaP / 2) * Math.sin(deltaP / 2) + Math.cos(p1) * Math.cos(p2) * Math.sin(deltaLambda / 2) * Math.sin(deltaLambda / 2);
    const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
    return R * c;
}

let distanzaAttuale = calcolaDistanza(incrocioLat, incrocioLon, ambLat, ambLon);
let distanzaPrecedente = context.get('distanzaPrecedente') || Infinity;
let statoOndaVerde = context.get('statoOndaVerde') || "SPENTA";
let emergenzaInCorso = context.get('emergenzaInCorso') || false;

let inAvvicinamento = distanzaAttuale < distanzaPrecedente;
let sottoSoglia = distanzaAttuale <= 300;

context.set('distanzaPrecedente', distanzaAttuale);
let msgDistanza = { payload: Math.round(distanzaAttuale) };

// Salviamo i dati puri dell'ambulanza prima di sovrascrivere il payload
// Questo garantisce che Ollama riceva tutte le statistiche intatte
let datiAmbulanzaBackup = { ...msg.payload };

// --- CASE A: GREEN WAVE ACTIVATION (< 300m) ---
if (sottoSoglia && sirena === true && statoOndaVerde === "SPENTA" && inAvvicinamento) {
    context.set('emergenzaInCorso', true);
    context.set('statoOndaVerde', "ATTIVA");

    msg.payload = {
        "command": "green_wave",
        "action": "force_green",
        "distance_m": Math.round(distanzaAttuale)
    };

    let msgResetReport = {
        payload: "⏳ Green Wave active. Waiting for the ambulance to cross the intersection to generate the operational report..."
    };

    return [msg, msgDistanza, msgResetReport, null];
}

// --- CASE A.2: GREEN WAVE DEACTIVATION AND OLLAMA TRIGGER ---
// L'IA scatta ora: l'ambulanza si sta allontanando e ha superato i 300 metri
if (statoOndaVerde === "ATTIVA" && !inAvvicinamento && distanzaAttuale > 300) {
    context.set('statoOndaVerde', "SPENTA");

    let msgSblocco = {
        payload: {
            "command": "normal",
            "action": "standard_cycle",
            "distance_m": Math.round(distanzaAttuale)
        }
    };

    // Inneschiamo la generazione del prompt LLM dal cavo numero 4
    let msgPerOllama = {
        dati_emergenza: datiAmbulanzaBackup,
        payload: "AI Trigger"
    };

    return [msgSblocco, msgDistanza, null, msgPerOllama];
}

// --- CASE B: EMERGENCY FINISHED (Arrived at hospital) ---
if (sirena === false && emergenzaInCorso === true) {
    context.set('emergenzaInCorso', false);
    context.set('statoOndaVerde', "SPENTA");

    msg.payload = {
        "event_status": "Ambulance arrived at destination."
    };

    return [null, msgDistanza, null, null];
}

// Standard behavior (waiting)
return [null, msgDistanza, null, null];

let datiInArrivo = msg.payload;
let coloreSirena;

// Controlliamo se c'è un'emergenza in corso
if (datiInArrivo.siren_active === true) {
    // MAGIA LAMPEGGIANTE (Rosso/Blu)
    let isRed = context.get('isRed') || false;
    isRed = !isRed;
    context.set('isRed', isRed);
    coloreSirena = isRed ? "red" : "blue";
} else {
    // AMBULANZA A RIPOSO: Rimane del suo colore standard (Rosso)
    coloreSirena = "red";
}

msg.payload = {
    name: "Ambulance_EMS",
    lat: datiInArrivo.latitude,
    lon: datiInArrivo.longitude,
    icon: "ambulance",
    iconColor: coloreSirena,       // Cambia in base all'emergenza o resta fissa!
    extraclass: "fa-solid",

    command: {
        lat: datiInArrivo.latitude,
        lon: datiInArrivo.longitude,
        zoom: 14
    }
};

return msg;

msg.payload = {
    name: "Smart_Intersection",
    lat: 44.3995,
    lon: 8.9851,
    icon: "circle",          // Stessa identica forma del semaforo dinamico!
    iconColor: "gray",       // Parte grigio (in attesa di connessione)
    extraclass: "fa-solid"
};
return msg;

// 1. Recuperiamo la copia dei dati dell'ambulanza
let dati_amb = msg.dati_emergenza;

// 2. Recuperiamo il meteo estratto dal nodo OpenWeatherMap
let meteo_desc = msg.payload.weather;
let meteo_temp = msg.payload.tempc;

// 3. Recuperiamo i dati del traffico salvati in memoria dal sensore virtuale!
let autoInCoda = flow.get("traffico_snapshot") || 0;
let statoTraffico = flow.get("stato_snapshot") || "Unknown";

// 4. Creiamo un "Prompt Agente" severo e direttivo in INGLESE per Llama
let promptIA = `You are a traffic control operator. Ambulance EMS-1 has just completed an emergency response.
Technical data: ${JSON.stringify(dati_amb)}.
Traffic at the intersection: ${autoInCoda} waiting vehicles (Congestion level: ${statoTraffico}).
Current weather: ${meteo_desc}, ${meteo_temp}°C.

Write an Operational Report IN ENGLISH (maximum 3 sentences).
STRICT RULES TO FOLLOW:
1. MAIN TOPIC: The absolute focus must be on the success of the "Green Wave" system, specifying how it allowed bypassing the traffic of ${autoInCoda} vehicles.
2. SECONDARY TOPIC: Dedicate ONLY THE LAST half sentence to the weather, briefly mentioning it as a contextual factor.
3. STYLE: Formal, cold, technical, and institutional.`;

// 5. Inviamo l'ordine a Ollama
msg.payload = {
    "model": "llama3.2",
    "prompt": promptIA,
    "stream": false
};

return msg;

// Check safely where Ollama has placed the text response
let aiText = "";

if (typeof msg.payload === "string") {
    try {
        let parsed = JSON.parse(msg.payload);
        aiText = parsed.response || (parsed.message && parsed.message.content) || msg.payload;
    } catch (e) {
        aiText = msg.payload;
    }
} else if (typeof msg.payload === "object" && msg.payload !== null) {
    // Standard handling for Ollama response object (supports both generation and chat)
    aiText = msg.payload.response || (msg.payload.message && msg.payload.message.content) || JSON.stringify(msg.payload);
}

// Assign the cleaned string to the payload for the dark terminal
msg.payload = aiText;
return msg;

// Safely extract the command
let comando = msg.payload && msg.payload.command ? msg.payload.command : "unknown";

if (comando === "green_wave") {
    msg.payload = "ACTIVE";
}
else if (comando === "normal") {
    msg.payload = "INACTIVE";
}
else {
    // Kill phantom messages from old tests
    msg.payload = "INACTIVE";
}

return msg;

// 1. Salvo i dati in memoria per quando Ollama farà il report finale
flow.set("auto_in_coda", msg.payload.cars_waiting);
flow.set("stato_traffico", msg.payload.traffic_status);

// 2. Preparo solo il numero delle auto per mandarlo al grafico di Grafana
msg.payload = msg.payload.cars_waiting;

return msg;

// We take a "snapshot" of the traffic at the exact moment the emergency activates
let current_cars = flow.get("auto_in_coda") || 0;
let current_status = flow.get("stato_traffico") || "Unknown";

// We save the snapshot in a safe storage
flow.set("traffico_snapshot", current_cars);
flow.set("stato_snapshot", current_status);

return msg;

let stato = msg.payload.Light_State;

if (stato === "Green") {
    msg.payload = "GREEN";
    msg.color = "green";
}
else if (stato === "Red") {
    msg.payload = "RED";
    msg.color = "red";
}
else if (stato === "Blocked_by_Pedestrian") {
    msg.payload = "RED (PEDESTRIAN)";
    msg.color = "red";
}
else {
    msg.payload = "UNKNOWN";
    msg.color = "gray";
}

return msg;

// Se c'è il pedone invia true, altrimenti false
if (msg.payload && msg.payload.Pedestrian_detected === true) {
    msg.payload = true;
} else {
    msg.payload = false;
}
return msg;

// Colore di base quando l'ospedale è "tranquillo"
let colorePulsante = "red";

// Se l'ambulanza è in emergenza, facciamo pulsare l'ospedale!
if (msg.payload.siren_active === true) {
    let isDark = context.get('isDark') || false;
    isDark = !isDark;
    context.set('isDark', isDark);

    // Scegliamo il colore lampeggiante
    colorePulsante = isDark ? "darkred" : "red";
}

msg.payload = {
    name: "Arrival",
    lat: 44.3915,
    lon: 8.9930,
    icon: "h-square",
    iconColor: colorePulsante,   // 🔴 Lampeggia in emergenza, resta rosso fisso a riposo!
    extraclass: "fa-solid"
};

return msg;

// 1. Leggiamo lo stato mandato dall'ESP32 o dal sistema
let statoSemaforo = msg.payload.Light_State;

// 2. Prepariamo il colore (Di base è GRIGIO = Spento/Sconosciuto)
let coloreNuovo = "gray";

if (statoSemaforo === "Red") {
    coloreNuovo = "red";
} else if (statoSemaforo === "Green") {
    coloreNuovo = "green";
} else if (statoSemaforo === "Blocked_by_Pedestrian") {
    coloreNuovo = "#ff0000";
}

// 3. LA MAGIA ANTI-SFARFALLIO: Leggiamo la memoria
let colorePrecedente = context.get('colorePrecedente');

// Se il colore calcolato è IDENTICO a quello che è già sulla mappa, FERMATI QUI!
if (coloreNuovo === colorePrecedente) {
    return null; // Non mandare niente alla mappa, così non sfarfalla
}

// Se invece il colore è cambiato davvero, salviamolo in memoria per la prossima volta
context.set('colorePrecedente', coloreNuovo);

// 4. Creiamo il comando per aggiornare la mappa
msg.payload = {
    name: "Smart_Intersection",    // ATTENZIONE: Deve essere uguale al nome nell'Init!
    lat: 44.3995,
    lon: 8.9851,
    icon: "circle",                // Usiamo il cerchio classico pulito
    iconColor: coloreNuovo,        // 🟢🔴 Il colore che cambia!
    extraclass: "fa-solid"
};

return msg;

// This script intercepts traffic light messages and turns them into an elegant report for Excel

// 1. Retrieve how many cars were in queue at that moment (thanks to memory!)
let carsInQueue = flow.get("traffico_snapshot") || 0;

// 2. Prepare precise and readable date and time
let currentDate = new Date().toLocaleDateString("it-IT");
let currentTime = new Date().toLocaleTimeString("it-IT");

// 3. Translate technical commands into human-readable language
let eventType = "Unknown";
let trafficLightAction = "None";
let bypassedCars = 0;

if (msg.payload.command === "green_wave") {
    eventType = "Green Wave Activation";
    trafficLightAction = "Intersection Locked (Ambulance Priority)";
    bypassedCars = carsInQueue; // We put the number of cars only when it activates!
} else if (msg.payload.command === "normal") {
    eventType = "Emergency End";
    trafficLightAction = "Normal Cycle Restoration";
    bypassedCars = "-";
} else {
    // If it's an unexpected message, we block it
    return null;
}

// 4. Create the perfect format for Excel
msg.payload = {
    "Date": currentDate,
    "Time": currentTime,
    "Event": eventType,
    "System Action": trafficLightAction,
    "Cars Bypassed": bypassedCars,
    "Activation Distance (m)": msg.payload.distance_m || 0
};

return msg;

// Clone the message so we don't mess up the rest of the flow
let nuovoMsg = { payload: {} };

// If the command is green_wave, save 1, otherwise save 0
if (msg.payload.command === "green_wave") {
    nuovoMsg.payload.stato_onda = 1;
} else if (msg.payload.command === "normal") {
    nuovoMsg.payload.stato_onda = 0;
} else {
    // If it's neither (maybe it's just the distance), don't save anything
    return null;
}

return nuovoMsg;

// 1. Se il sistema è appena partito o non ci sono dati
if (!msg.payload || typeof msg.payload.siren_active === "undefined") {
    msg.payload = "NOT AVAILABLE";
    return msg;
}

// 2. Se i dati ci sono, controlliamo lo stato
if (msg.payload.siren_active === true) {
    msg.payload = "EMERGENCY IN PROGRESS";
} else {
    msg.payload = "NORMAL";
}

return msg;
